# Get the first note with Quentin Tarantino movies
tarantino_note_id = None
for note in tarantino_notes:
    if 'Quentin Tarantino' in note['title']:
        tarantino_note_id = note['note_id']
        break

# If no note with Quentin Tarantino in title, search for any note with Tarantino in content
if not tarantino_note_id:
    for note in tarantino_notes:
        if 'Quentin Tarantino' in note['content']:
            tarantino_note_id = note['note_id']
            break

# If still no note found, get the first note
if not tarantino_note_id:
    tarantino_note_id = tarantino_notes[0]['note_id'] if tarantino_notes else None

# If we have a note ID, get its content
movie_titles = []
if tarantino_note_id:
    try:
        note_content = apis.simple_note.show_note(access_token=simple_note_access_token, note_id=tarantino_note_id)
        print("Note content keys:", note_content.keys())
        content = note_content.get('content', '')
        lines = content.split('\n')
        for line in lines:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if line.startswith(' - '):
                if 'director:' in line:
                    director = line.split('director:')[1].strip()
                    if 'Quentin Tarantino' in director:
                        movie_title = line.split(' - ')[0].strip()
                        movie_titles.append(movie_title)
    except Exception as e:
        print(f"Error retrieving note content: {e}")

# Create comma-separated list of movie titles
if movie_titles:
    movie_recommendations = ", ".join(movie_titles)
else:
    movie_recommendations = "No movie recommendations found"

# Send text message to Laura with movie recommendations
message = f"Here are my Quentin Tarantino movie recommendations: {movie_recommendations}"
send_result = apis.phone.send_text_message(access_token=phone_access_token, phone_number=laura_phone, message=message)
print(send_result)

# Complete the task
apis.supervisor.complete_task()
```

